namespace bonds {

// Declarations (so functions can call each other in any order).
double bond_price(double face, double coupon_rate, double ytm, long long years, long long freq = 2);
double macaulay_duration(double face, double coupon_rate, double ytm, long long years, long long freq = 2);
double modified_duration(double face, double coupon_rate, double ytm, long long years, long long freq = 2);
double convexity(double face, double coupon_rate, double ytm, long long years, long long freq = 2);
double ytm_newton(double price, double face, double coupon_rate, long long years, long long freq = 2);
long long payments_remaining(long long months_to_maturity, long long freq);

/// Clean price on a coupon date of a bond paying `freq` coupons a year.
inline double bond_price(double face, double coupon_rate, double ytm, long long years, long long freq) {
    if (freq <= 0 || years <= 0) {
        throw qt::ValueError("years and freq must be positive");
    }
    long long n = qt::imul(years, freq);
    double c = face * coupon_rate / static_cast<double>(freq);
    double y = ytm / static_cast<double>(freq);
    double price = 0.0;  // starts as an int; becomes a float as coupons are added
    for (long long k = 1; k < qt::iadd(n, 1LL); ++k) {
        price += c / std::pow(1 + y, static_cast<double>(k));
    }
    price += face / std::pow(1 + y, static_cast<double>(n));
    return price;
}

/// Present-value-weighted average time to the cash flows, in years.
inline double macaulay_duration(double face, double coupon_rate, double ytm, long long years, long long freq) {
    long long n = qt::imul(years, freq);
    double c = face * coupon_rate / static_cast<double>(freq);
    double y = ytm / static_cast<double>(freq);
    double weighted = 0.0;
    double pv_total = 0.0;
    for (long long k = 1; k < qt::iadd(n, 1LL); ++k) {
        double cf = k == n ? c + face : c;
        double pv = cf / std::pow(1 + y, static_cast<double>(k));
        weighted += static_cast<double>(k) / static_cast<double>(freq) * pv;
        pv_total += pv;
    }
    return weighted / pv_total;
}

inline double modified_duration(double face, double coupon_rate, double ytm, long long years, long long freq) {
    return macaulay_duration(face, coupon_rate, ytm, years, freq) / (1 + ytm / static_cast<double>(freq));
}

inline double convexity(double face, double coupon_rate, double ytm, long long years, long long freq) {
    long long n = qt::imul(years, freq);
    double c = face * coupon_rate / static_cast<double>(freq);
    double y = ytm / static_cast<double>(freq);
    double total = 0.0;
    double price = 0.0;
    for (long long k = 1; k < qt::iadd(n, 1LL); ++k) {
        double cf = k == n ? c + face : c;
        double pv = cf / std::pow(1 + y, static_cast<double>(k));
        total += pv * static_cast<double>(k) * static_cast<double>(k + 1);
        price += pv;
    }
    return total / (price * std::pow(1 + y, 2) * static_cast<double>(qt::ipow(freq, 2)));
}

/// Yield to maturity by Newton's method on price(y) - price = 0.
inline double ytm_newton(double price, double face, double coupon_rate, long long years, long long freq) {
    if (price <= 0) {
        throw qt::ValueError("price must be positive");
    }
    double y = coupon_rate > 0 ? coupon_rate : 0.05;
    for (long long _ = 0; _ < 100; ++_) {
        double p = bond_price(face, coupon_rate, y, years, freq);
        // dP/dy = -modified duration * price
        double dp = -modified_duration(face, coupon_rate, y, years, freq) * p;
        double step = (p - price) / dp;
        y -= step;
        if (std::fabs(step) < 1e-14) {
            return y;
        }
    }
    throw qt::RuntimeError("yield did not converge");
}

/// Coupons still to come; uses Python floor division and modulo semantics.
inline long long payments_remaining(long long months_to_maturity, long long freq) {
    long long months_per_coupon = qt::floordiv(12LL, freq);
    long long full = qt::floordiv(months_to_maturity, months_per_coupon);
    long long part = qt::mod(months_to_maturity, months_per_coupon);
    return qt::iadd(full, part > 0 ? 1LL : 0LL);
}

}  // namespace bonds
